// ===== 바꿀 값은 이 노드에만 있습니다 =====
const cfg = {
  githubOwner: 'YOUR-GITHUB-ID',
  githubRepo: 'invest-news-site',
  githubBranch: 'main',
  siteUrl: 'https://invest-news-site.vercel.app',
  supabaseUrl: 'https://YOUR-PROJECT.supabase.co',
  vaultRepo: 'invest-vault', // 비우면 옵시디안 노트를 만들지 않음
  vaultBranch: 'main',

  geminiModel: 'gemini-3.8-flash',
  fallbackModel: 'gemini-flash-lite-latest',
  embeddingModel: 'gemini-embedding-001',
  embedDim: 768,
  // 다른 AI의 투자 관점 Q&A: 기본(primary)이 실패하거나 한도에 걸리면 예비(fallback)로 넘어감
  // 둘 다 OpenAI 방식 요청을 받는 무료 서비스. 모델 이름은 각 서비스의 모델 목록에서 확인
  qaPrimary: {
    name: 'GitHub Models',
    url: 'https://models.github.ai/inference/chat/completions',
    model: 'openai/gpt-4.1-mini',
    maxChars: 6000, // 무료 등급은 요청당 입력 길이 제한이 작아 자료를 줄여 보냄
  },
  qaFallback: {
    name: 'Groq',
    url: 'https://api.groq.com/openai/v1/chat/completions',
    model: 'openai/gpt-oss-120b', // 안 되면 'llama-3.3-70b-versatile'
    maxChars: 30000,
  },
  secUserAgent: 'invest-news-site your-email@example.com',

  filingDays: 30, // 국내 공시 조회 기간
  secDays: 90, // 미국 SEC 서류 조회 기간
  newsDays: 7, // 뉴스 조회 기간
  kbDays: 180, // 지식베이스 과거 맥락 조회 기간
  maxFilings: 15,
  maxNews: 30,
  maxContext: 12,
  // 리서치에서 뺄 반복성 공시 (보고서명에 들어 있으면 제외)
  dartNoise: ['임원ㆍ주요주주특정증권등소유상황보고서', '최대주주등소유주식변동신고서', '특수관계인'],

  testTopic: '삼성전자 HBM', // n8n에서 직접 실행할 때 쓰는 시험용 주제 (Discord로 결과를 보내지 않음)
};

const input = $input.first().json || {};
const now = new Date();
const kst = (d) => new Date(d.getTime() + 9 * 3600_000).toISOString();
const ymd8 = (d) => kst(d).slice(0, 10).replace(/-/g, '');
const fromDiscord = !!(input.topic && input.appId && input.token);
const topic = String(input.topic || cfg.testTopic).trim().slice(0, 100);

const interpretText = `너는 한국 개인 투자자의 리서치 보조다. 사용자가 조사하려는 주제를 해석하라.

주제: ${topic}

출력: JSON 하나만.
{"title": 한국어 리포트 제목(30자 이내),
 "slug": 영어 소문자·숫자·하이픈 2~5단어,
 "companies": [주제의 중심이 되는 상장사 최대 3개. 국내는 {"name": 한국거래소 상장 종목명, "market": "KR"}, 미국은 {"name": 회사명, "market": "US", "ticker": 티커}. 특정 기업이 아닌 주제면 빈 배열],
 "queriesKo": [국내 뉴스 검색어 1~3개, 짧게],
 "queriesEn": [해외 뉴스 영어 검색어 0~2개. 해외와 관련이 없으면 빈 배열],
 "focus": 투자자 입장에서 조사 초점 한 문장}`;

return [{
  json: {
    ...cfg,
    topic,
    fromDiscord,
    followUrl: fromDiscord ? `https://discord.com/api/v10/webhooks/${input.appId}/${input.token}` : '',
    nowIso: now.toISOString(),
    today: kst(now).slice(0, 10),
    stamp: kst(now).slice(0, 16).replace('T', '-').replace(':', ''),
    endDe: ymd8(now),
    bgnDe: ymd8(new Date(now.getTime() - cfg.filingDays * 86400_000)),
    interpretBody: {
      contents: [{ role: 'user', parts: [{ text: interpretText }] }],
      generationConfig: { responseMimeType: 'application/json', maxOutputTokens: 4096 },
    },
  },
}];

// 회사명 비교용 키: 대문자, (주)·법인 접미사·기호 제거. 종목 사전과 게시 워크플로가 같은 규칙을 씀
function nameKey(s) {
  let t = String(s || '').toUpperCase();
  t = t.replace(/\(주\)|㈜|주식회사|\(유\)/g, ' ').replace(/&/g, ' AND ').replace(/\/[A-Z]{2}\/?\s*$/, ' ');
  t = t.replace(/[.,'’"()\-\/:;!]/g, ' ');
  const STOP = new Set(['INC', 'INCORPORATED', 'CORP', 'CORPORATION', 'CO', 'COMPANY', 'LTD', 'LIMITED', 'PLC', 'HOLDINGS', 'HOLDING', 'GROUP', 'THE', 'CLASS', 'A', 'B', 'C', 'SA', 'NV', 'AG', 'SE', 'LLC', 'LP', 'ADR', 'DE', 'TECHNOLOGIES', 'TECHNOLOGY']);
  return t.split(/\s+/).filter((w) => w && !STOP.has(w)).join('');
}
// Gemini 응답에서 글자만 꺼내고, JSON이면 읽어 줍니다.
function geminiText(j) {
  const parts = ((((j || {}).candidates || [])[0] || {}).content || {}).parts || [];
  return parts.filter((p) => !p.thought).map((p) => p.text || '').join('');
}
function parseJson(t) {
  t = String(t || '').trim().replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '');
  try { return JSON.parse(t); } catch (e) {}
  const a = t.indexOf('{'), b = t.lastIndexOf('}');
  if (a >= 0 && b > a) { try { return JSON.parse(t.slice(a, b + 1)); } catch (e) {} }
  return null;
}
// 주제 해석 결과를 정리합니다. Gemini가 실패해도 주제 그대로 검색할 수 있게 기본값을 둡니다.
const c = $('설정').first().json;
const o = parseJson(geminiText($input.first().json)) || {};
const arr = (v, n) => (Array.isArray(v) ? v.map((x) => String(x).trim()).filter(Boolean).slice(0, n) : []);
const companies = Array.isArray(o.companies) ? o.companies.filter((x) => x && x.name).slice(0, 3).map((x) => ({ name: String(x.name).slice(0, 40), market: x.market === 'US' ? 'US' : 'KR', ticker: x.ticker ? String(x.ticker).toUpperCase().trim() : '' })) : [];
const slug = String(o.slug || '').toLowerCase().replace(/[^a-z0-9-]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 40) || 'report';
const plan = {
  title: String(o.title || c.topic).slice(0, 40),
  slug: `${c.stamp}-${slug}`,
  companies,
  queriesKo: arr(o.queriesKo, 3).length ? arr(o.queriesKo, 3) : [c.topic],
  queriesEn: arr(o.queriesEn, 2),
  focus: String(o.focus || '').slice(0, 200),
  interpreted: !!o.title,
};
return [{
  json: {
    plan,
    keys: companies.map((x) => nameKey(x.name)).filter(Boolean),
    tickers: companies.map((x) => x.ticker).filter(Boolean),
  },
}];

// 회사명 비교용 키: 대문자, (주)·법인 접미사·기호 제거. 종목 사전과 게시 워크플로가 같은 규칙을 씀
function nameKey(s) {
  let t = String(s || '').toUpperCase();
  t = t.replace(/\(주\)|㈜|주식회사|\(유\)/g, ' ').replace(/&/g, ' AND ').replace(/\/[A-Z]{2}\/?\s*$/, ' ');
  t = t.replace(/[.,'’"()\-\/:;!]/g, ' ');
  const STOP = new Set(['INC', 'INCORPORATED', 'CORP', 'CORPORATION', 'CO', 'COMPANY', 'LTD', 'LIMITED', 'PLC', 'HOLDINGS', 'HOLDING', 'GROUP', 'THE', 'CLASS', 'A', 'B', 'C', 'SA', 'NV', 'AG', 'SE', 'LLC', 'LP', 'ADR', 'DE', 'TECHNOLOGIES', 'TECHNOLOGY']);
  return t.split(/\s+/).filter((w) => w && !STOP.has(w)).join('');
}
// 해석된 회사를 종목 사전과 맞춰 조사 대상을 정합니다. 사전에 없는 회사는 뉴스 검색에만 씁니다.
const { plan } = $('해석 정리').first().json;
const ctx = $input.first().json || {};
const symbols = Array.isArray(ctx.symbols) ? ctx.symbols : [];
const watch = Array.isArray(ctx.watchlist) ? ctx.watchlist : [];
const label = Object.fromEntries(watch.map((w) => [`${w.market}:${w.code}`, w.name]));
const targets = [];
for (const x of plan.companies) {
  const hit = (x.market === 'US' && x.ticker && symbols.find((s) => s.market === 'US' && s.code === x.ticker))
    || symbols.find((s) => s.market === x.market && s.name_key === nameKey(x.name));
  if (!hit) { targets.push({ market: x.market, name: x.name }); continue; }
  if (targets.some((t) => t.code === hit.code && t.market === hit.market)) continue;
  targets.push({
    market: hit.market, code: hit.code, corp_code: hit.corp_code, cik: hit.cik,
    name: label[`${hit.market}:${hit.code}`] || (hit.market === 'KR' ? hit.name : x.name),
    fullName: hit.name,
  });
}
const c = $('설정').first().json;
const bgText = `한국 개인 투자자를 위해 다음 주제의 배경을 웹 검색으로 확인해 한국어로 정리하라. 최근 동향, 관련 산업 구조, 주요 수치, 시장이 주목하는 쟁점을 5~8문장으로. 매수·매도 권유나 가격 예측은 쓰지 말고, 확실하지 않은 내용은 쓰지 마라.
주제: ${c.topic}
초점: ${plan.focus || c.topic}
관련 종목: ${targets.map((t) => t.fullName || t.name).join(', ') || '(없음)'}`;
const kbText = [c.topic, plan.focus, ...targets.map((t) => t.name)].filter(Boolean).join(' / ');
return [{
  json: {
    plan,
    targets,
    backgroundBody: { contents: [{ role: 'user', parts: [{ text: bgText }] }], tools: [{ google_search: {} }] },
    embedBody: { content: { parts: [{ text: kbText }] }, taskType: 'RETRIEVAL_QUERY', outputDimensionality: c.embedDim },
  },
}];

// 국내 대상 회사의 최근 공시 요청. 없으면 건너뛰기 요청 1개 (DART 응답만 무시함)
const c = $('설정').first().json;
const { targets } = $('조사 대상 정리').first().json;
const kr = targets.filter((t) => t.market === 'KR' && t.corp_code);
if (!kr.length) return [{ json: { skip: true, url: `https://opendart.fss.or.kr/api/list.json?bgn_de=${c.endDe}&end_de=${c.endDe}&page_count=1` } }];
return kr.map((t) => ({
  json: { target: t, url: `https://opendart.fss.or.kr/api/list.json?corp_code=${t.corp_code}&bgn_de=${c.bgnDe}&end_de=${c.endDe}&page_count=50` },
}));

// 미국 대상 회사의 SEC 서류 + Google News 검색 (국내·영어)
const { plan, targets } = $('조사 대상 정리').first().json;
const c = $('설정').first().json;
const out = [];
for (const t of targets) {
  if (t.market === 'US' && t.cik) out.push({ json: { kind: 'sec', target: t, url: `https://data.sec.gov/submissions/CIK${String(t.cik).padStart(10, '0')}.json` } });
}
const days = `when:${c.newsDays}d`;
for (const q of plan.queriesKo) out.push({ json: { kind: 'gnews', market: 'KR', url: `https://news.google.com/rss/search?q=${encodeURIComponent(`${q} ${days}`)}&hl=ko&gl=KR&ceid=KR:ko` } });
const en = [...plan.queriesEn, ...targets.filter((t) => t.market === 'US' && t.code).map((t) => `${t.code} stock`)].slice(0, 3);
for (const q of en) out.push({ json: { kind: 'gnews', market: 'US', url: `https://news.google.com/rss/search?q=${encodeURIComponent(`${q} ${days}`)}&hl=en-US&gl=US&ceid=US:en` } });
return out;

// 네이버 뉴스 검색 (국내 검색어 + 국내 대상 회사명)
const { plan, targets } = $('조사 대상 정리').first().json;
const qs = [...new Set([...plan.queriesKo, ...targets.filter((t) => t.market === 'KR').map((t) => t.name)])].slice(0, 4);
if (!qs.length) return [{ json: { skip: true, url: 'https://openapi.naver.com/v1/search/news.json?query=skip&display=1' } }];
return qs.map((q) => ({ json: { query: q, url: `https://openapi.naver.com/v1/search/news.json?query=${encodeURIComponent(q)}&display=30&sort=date` } }));

// 지식베이스 검색 요청: 질문 임베딩을 길이 1로 맞추고, 대상 종목이 있으면 그 종목으로 거름
const c = $('설정').first().json;
const { targets } = $('조사 대상 정리').first().json;
const v = ((($input.first().json || {}).embedding) || {}).values || [];
if (v.length !== c.embedDim) return [{ json: { skip: true, body: null } }];
const norm = Math.sqrt(v.reduce((s, x) => s + x * x, 0)) || 1;
const codes = targets.filter((t) => t.code).map((t) => t.code);
return [{
  json: {
    body: {
      query_embedding: v.map((x) => Math.round((x / norm) * 1e6) / 1e6),
      match_count: c.maxContext,
      filter_codes: codes.length ? codes : null,
      since: new Date(Date.now() - c.kbDays * 86400_000).toISOString(),
      include_ai: true,
    },
  },
}];

// Gemini 응답에서 글자만 꺼내고, JSON이면 읽어 줍니다.
function geminiText(j) {
  const parts = ((((j || {}).candidates || [])[0] || {}).content || {}).parts || [];
  return parts.filter((p) => !p.thought).map((p) => p.text || '').join('');
}
function parseJson(t) {
  t = String(t || '').trim().replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '');
  try { return JSON.parse(t); } catch (e) {}
  const a = t.indexOf('{'), b = t.lastIndexOf('}');
  if (a >= 0 && b > a) { try { return JSON.parse(t.slice(a, b + 1)); } catch (e) {} }
  return null;
}
// 모은 자료(공시·뉴스·과거 맥락·배경)에 번호를 붙이고, 리포트와 ChatGPT 요청을 만듭니다.
// 모델은 번호로만 근거를 대고 URL은 만들지 않습니다.
const c = $('설정').first().json;
const { plan, targets } = $('조사 대상 정리').first().json;
const now = Date.parse(c.nowIso);
const paired = (it) => { const p = it.pairedItem; return Array.isArray(p) ? (p[0] ? p[0].item : 0) : p && typeof p.item === 'number' ? p.item : 0; };
const kstDay = (iso) => new Date(Date.parse(iso) + 9 * 3600_000).toISOString().slice(0, 10);
const NAMED = { amp: '&', lt: '<', gt: '>', quot: '"', apos: "'", nbsp: ' ' };
const decode = (s) => String(s || '').replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g, '$1').replace(/&#(\d+);/g, (_, d) => String.fromCodePoint(+d)).replace(/&([a-z]+);/gi, (m, n) => NAMED[n.toLowerCase()] ?? m);
const strip = (s) => decode(decode(s).replace(/<[^>]*>/g, ' ')).replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim();
const tag = (b, n) => { const m = b.match(new RegExp(`<${n}(?:\\s[^>]*)?>([\\s\\S]*?)</${n}>`, 'i')); return m ? m[1] : ''; };
const TRUST = { '연합뉴스': 4, '연합인포맥스': 5, '한국경제': 4, '매일경제': 4, '서울경제': 3, '이데일리': 3, '머니투데이': 3, '조선일보': 4, '중앙일보': 4, '동아일보': 4, '한겨레': 4, '경향신문': 4, '뉴스1': 3, '뉴시스': 3, '더벨': 4, 'Reuters': 5, 'Bloomberg': 5, 'Associated Press': 5, 'The Wall Street Journal': 5, 'Financial Times': 5, 'CNBC': 4, 'MarketWatch': 4, "Barron's": 4, 'Yahoo Finance': 3 };
const DOMAINS = { 'yna.co.kr': '연합뉴스', 'einfomax.co.kr': '연합인포맥스', 'hankyung.com': '한국경제', 'mk.co.kr': '매일경제', 'sedaily.com': '서울경제', 'edaily.co.kr': '이데일리', 'mt.co.kr': '머니투데이', 'chosun.com': '조선일보', 'joongang.co.kr': '중앙일보', 'donga.com': '동아일보', 'hani.co.kr': '한겨레', 'khan.co.kr': '경향신문', 'news1.kr': '뉴스1', 'newsis.com': '뉴시스', 'thebell.co.kr': '더벨' };
const host = (u) => ((String(u).match(/^https?:\/\/([^/?#:]+)/i) || [])[1] || '').toLowerCase().replace(/^(www|m)\./, '');
const key = (u) => String(u).replace(/^https?:\/\/(www\.|m\.)?/i, '').replace(/[?#].*$/, '').replace(/\/+$/, '').toLowerCase();

// ---------- 공시 ----------
const filings = [];
const dReq = $('DART 요청 만들기').all().map((i) => i.json);
for (const it of $('DART 공시 조회').all()) {
  const req = dReq[paired(it)] || {};
  if (req.skip) continue;
  const b = (it.json || {}).body || it.json || {};
  for (const d of b.list || []) {
    if (c.dartNoise.some((n) => String(d.report_nm).includes(n))) continue;
    filings.push({ kind: 'filing', title: `[${d.corp_name}] ${String(d.report_nm).trim()}`, source: 'DART', url: `https://dart.fss.or.kr/dsaf001/main.do?rcpNo=${d.rcept_no}`, date: `${d.rcept_dt.slice(0, 4)}-${d.rcept_dt.slice(4, 6)}-${d.rcept_dt.slice(6, 8)}`, isAI: false, market: 'KR', sortKey: d.rcept_no });
  }
}
const ITEMS = { '1.01': '중요 계약 체결', '1.02': '중요 계약 종료', '2.01': '자산 인수·처분', '2.02': '실적 발표', '2.03': '채무 발생', '2.05': '구조조정', '2.06': '자산 손상', '5.02': '임원·이사 변동', '5.07': '주주총회 결과', '7.01': '공정공시', '8.01': '기타 중요 사항' };
const FORMS = ['8-K', '10-Q', '10-K', '6-K', '20-F'];

// ---------- SEC · Google News ----------
const news = [];
const wReq = $('SEC·뉴스 요청 만들기').all().map((i) => i.json);
for (const it of $('SEC·뉴스 조회').all()) {
  const req = wReq[paired(it)] || {};
  const j = it.json || {};
  const body = typeof j.body === 'string' ? j.body : typeof j.data === 'string' ? j.data : '';
  if (j.error || !j.statusCode || j.statusCode >= 400 || !body) continue;
  if (req.kind === 'sec') {
    let s; try { s = JSON.parse(body); } catch (e) { continue; }
    const r = (s.filings || {}).recent || {};
    for (let i = 0; i < (r.accessionNumber || []).length; i++) {
      if (!FORMS.includes(r.form[i])) continue;
      const t = Date.parse(r.acceptanceDateTime[i]) || Date.parse(r.filingDate[i]);
      if (!Number.isFinite(t) || now - t > c.secDays * 86400_000) continue;
      const items = String(r.items[i] || '').split(',').map((x) => x.trim()).filter((x) => ITEMS[x]);
      filings.push({ kind: 'filing', title: `[${req.target.code}] ${r.form[i]}${items.length ? `: ${items.map((x) => ITEMS[x]).join(', ')}` : ''}`, source: 'SEC EDGAR', url: `https://www.sec.gov/Archives/edgar/data/${Number(req.target.cik)}/${r.accessionNumber[i].replace(/-/g, '')}/${r.primaryDocument[i]}`, date: kstDay(new Date(t).toISOString()), isAI: false, market: 'US', sortKey: new Date(t).toISOString().replace(/\D/g, '') });
    }
    continue;
  }
  for (const b of body.match(/<item[\s>][\s\S]*?<\/item>/gi) || []) {
    const source = strip(tag(b, 'source')) || 'Google News';
    let title = strip(tag(b, 'title'));
    if (title.endsWith(` - ${source}`)) title = title.slice(0, -(source.length + 3));
    const t = Date.parse(strip(tag(b, 'pubDate')));
